  },
  methods: {
    // 标签页切换
    handleTabChange() {
      this.showResults = false;
    },
    // 患者信息相关
    showPatientInfoDialog() {
      this.isEditingPatient = false;
      this.editingPatientId = null;
      // 初始化一个空的患者表单
      this.patientForm = {
        name: "",
        gender: "male",
        age: 30,
        phone: "",
        note: "",
        leftEyeDiagnosis: "",
        rightEyeDiagnosis: "",
        leftEyeConfidence: 0,
        rightEyeConfidence: 0,
        finalDiagnosis: "",
        processTime: ""
      };
      this.patientInfoDialogVisible = true;
    },
    generatePatientId() {
      // 此方法保留为辅助功能，但不再自动调用
      const prefix = "PT";
      const date = new Date();
      const year = date.getFullYear();
      const nextNum = this.patientList.length + 1;
      return `${prefix}${year}${nextNum.toString().padStart(3, "0")}`;
    },
    async submitPatientInfo() {
      try {
        const valid = await this.$refs.patientFormRef.validate();
        if (valid) {
          if (this.isEditingPatient) {
            // 编辑现有患者
            const index = this.patientList.findIndex(p => p.id === this.editingPatientId);
            if (index !== -1) {
              // 保留诊断信息
              const diagnosisInfo = {
                leftEyeDiagnosis: this.patientList[index].leftEyeDiagnosis,
                rightEyeDiagnosis: this.patientList[index].rightEyeDiagnosis,
                leftEyeConfidence: this.patientList[index].leftEyeConfidence,
                rightEyeConfidence: this.patientList[index].rightEyeConfidence,
                finalDiagnosis: this.patientList[index].finalDiagnosis,
                processTime: this.patientList[index].processTime
              };

              // 发送编辑请求
              const response = await request({
                method: "put",
                url: `/patients/${this.editingPatientId}`,
                data: this.patientForm
              });
              if (response.code === 200) {
                this.$set(this.patientList, index, {
                  ...this.patientForm,
                  id: this.editingPatientId,
                  ...diagnosisInfo
                });
                this.$message.success("患者信息更新成功");
                this.patientInfoDialogVisible = false;
              } else {
                this.$message.error(response.msg || "更新失败，请重试");
              }
            }
          } else {
            // 添加新患者
            const response = await request({
              method: "post",
              url: "/patients/add",
              data: this.patientForm
            });
            if (response.code === 200) {
              // 添加到列表中，使用后端返回的ID
              this.patientList.push({
                ...this.patientForm,
                id: response.data.id,
                // 使用后端返回的ID
                leftEyeDiagnosis: "",
                rightEyeDiagnosis: "",
                leftEyeConfidence: 0,
                rightEyeConfidence: 0,
                finalDiagnosis: "",
                processTime: ""
              });
              this.$message.success("患者信息添加成功");
              this.patientInfoDialogVisible = false;
            } else {
              this.$message.error(response.msg || "添加失败，请重试");
            }
          }
        }
      } catch (error) {
        console.error("提交患者信息错误:", error);
        this.$message.error(error.response?.data?.msg || "操作失败，请稍后重试");
      }
    },
    editPatient(patient) {
      this.isEditingPatient = true;
      this.editingPatientId = patient.id;
      this.patientForm = {
        ...patient
      };
      this.patientInfoDialogVisible = true;
    },
    deletePatient(patient) {
      this.$confirm("此操作将永久删除该患者信息, 是否继续?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        const index = this.patientList.findIndex(p => p.id === patient.id);
        if (index !== -1) {
          this.patientList.splice(index, 1);
          this.$message.success("删除成功");

          // 如果删除的是当前选中的患者，清空选择
          if (this.selectedPatientId === patient.id) {
            this.selectedPatientId = "";
            this.selectedPatient = null;
          }

          // 从批量选择中移除
          if (this.selectedPatientIds.includes(patient.id)) {
            const idIndex = this.selectedPatientIds.indexOf(patient.id);
            this.selectedPatientIds.splice(idIndex, 1);
          }
        }
      }).catch(() => {
        this.$message.info("已取消删除");
      });
    },
    handlePatientSelect(patientId) {
      this.selectedPatient = this.patientList.find(p => p.id === patientId);
    },
    // 单图上传处理
    handleLeftEyeChange(file) {
      this.leftEyeFile = file.raw;
      this.leftEyeImage = URL.createObjectURL(file.raw);
    },
    handleRightEyeChange(file) {
      this.rightEyeFile = file.raw;
      this.rightEyeImage = URL.createObjectURL(file.raw);
    },
    removeLeftEye() {
      this.leftEyeFile = null;
      this.leftEyeImage = null;
    },
    removeRightEye() {
      this.rightEyeFile = null;
      this.rightEyeImage = null;
    },
    // 批量上传处理
    handleBatchChange(file, fileList) {
      this.batchFileList = fileList;
      this.analyzeBatchFiles();
    },
    handleBatchRemove(file, fileList) {
      this.batchFileList = fileList;
      this.analyzeBatchFiles();
    },
    clearBatchFiles() {
      this.batchFileList = [];
      this.pairedImages = [];
      this.unpairedImages = [];
    },
    analyzeBatchFiles() {
      // 分析文件名，配对左右眼图像
      const leftEyes = {};
      const rightEyes = {};
      const paired = [];
      const unpaired = [];

      // 正则表达式匹配ID和左右眼标识
      const regex = /^(\d+)_(left|right)\.(jpg|jpeg|png)/i;
      this.batchFileList.forEach(file => {
        const match = file.name.match(regex);
        if (match) {
          const id = match[1];
          const side = match[2].toLowerCase();
          if (side === "left") {
            leftEyes[id] = file;
          } else if (side === "right") {
            rightEyes[id] = file;
          }
        } else {
          unpaired.push(file);
        }
      });

      // 配对左右眼
      for (const id in leftEyes) {
        if (rightEyes[id]) {
          paired.push({
            id,
            leftEye: leftEyes[id],
            rightEye: rightEyes[id]
          });

          // 从未配对列表中移除已配对的文件
          delete leftEyes[id];
          delete rightEyes[id];
        }
      }

      // 剩余未配对的文件
      for (const id in leftEyes) {
        unpaired.push(leftEyes[id]);
      }
      for (const id in rightEyes) {
        unpaired.push(rightEyes[id]);
      }
      this.pairedImages = paired;
      this.unpairedImages = unpaired;
    },
    // 文件上传前验证
    beforeUpload(file) {
      // 验证文件名是否与选择的患者ID匹配
      if (this.activeTab === "single" && this.selectedPatientId) {
        const fileNameRegex = new RegExp(`^${this.selectedPatientId}`);
        if (!fileNameRegex.test(file.name)) {
          this.$message.warning(`文件名应以患者ID "${this.selectedPatientId}" 开头`);
          return false;
        }
      }
      const isImage = file.type.startsWith("image/");
      const isLt5M = file.size / 1024 / 1024 < 5;
      if (!isImage) {
        this.$message.error("只能上传图片文件!");
        return false;
      }
      if (!isLt5M) {
        this.$message.error("图片大小不能超过 5MB!");
        return false;
      }
      return false; // 阻止自动上传
    },
    // 处理图像
    async processSingleImages() {
      if (!this.selectedPatientId) {
        this.$message.warning("请先选择患者");
        return;
      }
      this.processingMode = "single";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;
      try {
        // 创建FormData对象
        const leftFormData = new FormData();
        const rightFormData = new FormData();

        // 添加文件到FormData
        leftFormData.append("file", this.leftEyeFile);
        rightFormData.append("file", this.rightEyeFile);

        // 上传左眼图像
        const leftResponse = await request({
          method: "post",
          url: "/common/upload",
          data: leftFormData,
          headers: {
            "Content-Type": "multipart/form-data"
          }
        });

        // 上传右眼图像
        const rightResponse = await request({
          method: "post",
          url: "/common/upload",
          data: rightFormData,
          headers: {
            "Content-Type": "multipart/form-data"
          }
        });
        if (leftResponse.code === 200 && rightResponse.code === 200) {
          // 获取上传后的文件路径
          const leftImagePath = leftResponse.data;
          const rightImagePath = rightResponse.data;

          // 调用诊断API
          const doctorId = localStorage.getItem("doctorId");
          const diagnosisResponse = await request({
            method: "post",
            url: "/diagnose",
            data: {
              patientId: this.selectedPatientId,
              doctorId: parseInt(doctorId),
              imagePaths: [leftImagePath, rightImagePath]
            }
          });
          if (diagnosisResponse.code === 200) {
            const result = diagnosisResponse.data;

            // 更新诊断结果
            this.singleResult = {
              leftEye: {
                diagnosis: this.getDiagnosisFromLabels(result.diseaseLeft.labels),
                confidence: Math.max(...result.diseaseLeft.probabilities) * 100,
                probabilities: result.diseaseLeft.probabilities
              },
              rightEye: {
                diagnosis: this.getDiagnosisFromLabels(result.diseaseRight.labels),
                confidence: Math.max(...result.diseaseRight.probabilities) * 100,
                probabilities: result.diseaseRight.probabilities
              },
              finalDiagnosis: result.finalResult,
              suggestion: this.generateSuggestion(this.diseaseCategories.indexOf(this.getDiagnosisFromLabels(result.diseaseLeft.labels)), this.diseaseCategories.indexOf(this.getDiagnosisFromLabels(result.diseaseRight.labels)))
            };

            // 更新患者诊断信息
            const patientIndex = this.patientList.findIndex(p => p.id === this.selectedPatientId);
            if (patientIndex !== -1) {
              const patient = this.patientList[patientIndex];
              patient.leftEyeDiagnosis = result.leftResult; // 使用API返回的左眼结果
              patient.rightEyeDiagnosis = result.rightResult; // 使用API返回的右眼结果
              patient.finalDiagnosis = result.finalResult; // 使用API返回的最终结果
              patient.leftEyeConfidence = Math.max(...result.diseaseLeft.probabilities) * 100;
              patient.rightEyeConfidence = Math.max(...result.diseaseRight.probabilities) * 100;
              patient.processTime = new Date().toLocaleString();
              this.$set(this.patientList, patientIndex, patient);
            }

            // 更新进度并显示结果
            this.processingPercentage = 100;
            setTimeout(() => {
              this.processingDialogVisible = false;
              this.updatePatientDiagnosis();
              this.showResults = true;

              // 添加到历史记录
              this.addToHistory(this.singleResult);

              // 渲染图表
              this.$nextTick(() => {
                this.renderEyeChart("leftEyeChart", this.singleResult.leftEye.probabilities);
                this.renderEyeChart("rightEyeChart", this.singleResult.rightEye.probabilities);
                this.renderComparisonChart(this.singleResult.leftEye.probabilities, this.singleResult.rightEye.probabilities);
              });
            }, 500);
          } else {
            throw new Error(diagnosisResponse.msg || "诊断失败");
          }
        } else {
          throw new Error("文件上传失败");
        }
      } catch (error) {
        console.error("处理图像错误:", error);
        this.$message.error(error.message || "图像处理失败，请稍后重试");
        this.processingDialogVisible = false;
      }
    },
    // 根据标签数组获取诊断结果
    getDiagnosisFromLabels(labels) {
      // 根据返回的标签数组中最可能的标签确定诊断结果
      if (labels && labels.length > 0) {
        const label = labels[0]; // 取第一个最可能的标签
        switch (label) {
          case "A":
            return "糖尿病视网膜病变";
          case "G":
            return "青光眼";
          case "C":
            return "白内障";
          case "H":
            return "高血压视网膜病变";
          case "M":
            return "近视";
          case "O":
            return "其他异常";
          case "N":
            return "正常";
          default:
            return "未知";
        }
      }
      return "未知";
    },
    updatePatientDiagnosis() {
      // 更新患者诊断信息
      if (this.selectedPatientId && this.singleResult) {
        const patientIndex = this.patientList.findIndex(p => p.id === this.selectedPatientId);
        if (patientIndex !== -1) {
          const patient = this.patientList[patientIndex];
          const now = new Date();
          patient.leftEyeDiagnosis = this.singleResult.leftEye.diagnosis;
          patient.leftEyeConfidence = this.singleResult.leftEye.confidence;
          patient.rightEyeDiagnosis = this.singleResult.rightEye.diagnosis;
          patient.rightEyeConfidence = this.singleResult.rightEye.confidence;
          patient.finalDiagnosis = this.singleResult.finalDiagnosis;
          patient.processTime = now.toLocaleString();
          this.$set(this.patientList, patientIndex, patient);
        }
      }
    },
    // 渲染左右眼比较柱状图
    renderComparisonChart(leftEyeProbs, rightEyeProbs) {
      const chartDom = this.$refs.comparisonChart;
      const myChart = echarts.init(chartDom);
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: params => {
            const disease = this.diseaseCategories[params[0].dataIndex];
            let result = `${disease}<br/>`;
            params.forEach(param => {
              const value = param.value;
              result += `${param.seriesName}: ${value}%<br/>`;
            });
            return result;
          }
        },
        legend: {
          data: ["左眼", "右眼"]
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: this.diseaseCategories
        },
        yAxis: {
          type: "value",
          name: "概率 (%)",
          max: 100
        },
        series: [{
          name: "左眼",
          type: "bar",
          data: leftEyeProbs.map(p => (p * 100).toFixed(1)),
          itemStyle: {
            color: "#409EFF"
          }
        }, {
          name: "右眼",
          type: "bar",
          data: rightEyeProbs.map(p => (p * 100).toFixed(1)),
          itemStyle: {
            color: "#FF6B6B"
          }
        }]
      };
      myChart.setOption(option);

      // 响应窗口大小变化
      window.addEventListener("resize", function () {
        myChart.resize();
      });
    },
    // 渲染单眼图表
    renderEyeChart(chartId, probabilities) {
      const chartDom = this.$refs[chartId];
      const myChart = echarts.init(chartDom);
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: params => {
            const dataIndex = params[0].dataIndex;
            const value = params[0].value;
            return `${this.diseaseCategories[dataIndex]}: ${value}%`;
          }
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: this.diseaseCategories.map(cat => cat.substring(0, 4) + "..."),
          axisLabel: {
            interval: 0,
            rotate: 45
          }
        },
        yAxis: {
          type: "value",
          axisLabel: {
            formatter: "{value}%"
          },
          max: 100
        },
        series: [{
          name: "概率",
          type: "bar",
          data: probabilities.map(p => (p * 100).toFixed(2)),
          itemStyle: {
            color: function (params) {
              const colorList = ["#FF5252",
              // 糖尿病
              "#7C4DFF",
              // 青光眼
              "#448AFF",
              // 白内障
              "#FFC107",
              // AMD
              "#FF9800",
              // 高血压
              "#00BCD4",
              // 近视
              "#9C27B0",
              // 其他异常
              "#4CAF50" // 正常
              ];
              return colorList[params.dataIndex];
            }
          }
        }]
      };
      myChart.setOption(option);

      // 响应窗口大小变化
      window.addEventListener("resize", function () {
        myChart.resize();
      });
    },
    // 生成建议
    generateSuggestion(leftIndex, rightIndex) {
      // 根据诊断结果生成建议
      const suggestions = {
        0: "建议进行血糖控制，定期复查眼底，必要时考虑激光或抗VEGF治疗。",
        1: "建议测量眼压，进行视野检查，必要时使用降眼压药物。",
        2: "建议进行视力矫正，必要时考虑白内障手术。",
        3: "建议定期监测黄斑区变化，必要时考虑抗VEGF治疗。",
        4: "建议控制血压，定期复查眼底。",
        5: "建议进行屈光矫正，控制近距离用眼时间。",
        6: "建议进一步检查确定具体异常类型。",
        7: "眼底未见明显异常，建议定期检查。"
      };
      if (leftIndex === rightIndex) {
        return suggestions[leftIndex];
      } else {
        return `左眼：${suggestions[leftIndex]}\n右眼：${suggestions[rightIndex]}`;
      }
    },
    // 报告操作
    saveReport() {
      this.$message.success("报告已保存到系统");
    },
    exportReport() {
      this.$message.success("报告已导出为PDF文件");
    },
    viewBatchDetail(row) {
      // 查看批量诊断中的单个详情
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportBatchReport(row) {
      this.$message.success(`ID ${row.id} 的报告已导出为PDF文件`);
    },
    saveAllBatchReports() {
      this.$message.success(`已保存全部 ${this.batchResults.length} 份报告`);
    },
    exportAllBatchReports() {
      this.$message.success(`已导出全部 ${this.batchResults.length} 份报告为PDF文件`);
    },
    // 历史记录操作
    addToHistory(result) {
      const now = new Date();
      const timeStr = now.toLocaleString();
      this.historyRecords.unshift({
        ...result,
        time: timeStr
      });
    },
    viewHistoryDetail(row) {
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportHistoryReport(row) {
      this.$message.success(`历史记录 ID ${row.id} 的报告已导出为PDF文件`);
    },
    processBatchImages() {
      if (this.selectedPatientIds.length === 0) {
        this.$message.warning("请先选择患者");
        return;
      }
      this.processingMode = "batch";
      this.processingDialogVisible = true;
      this.processingPercentage = 0;
      this.processedCount = 0;
      this.totalProcessCount = this.pairedImages.length;

      // 创建任务队列
      this.taskQueue = this.pairedImages.map((pair, index) => ({
        id: pair.id,
        status: index === 0 ? "processing" : "waiting"
      }));
      this.currentTaskIndex = 0;

      // 模拟批量处理过程
      this.processBatchTask();
    },
    async processBatchTask() {
      if (this.currentTaskIndex >= this.taskQueue.length) {
        // 所有任务处理完成
        setTimeout(() => {
          this.processingDialogVisible = false;
          this.generateBatchResults();
          this.updateBatchPatientDiagnosis();
          this.showResults = true;
        }, 500);
        return;
      }
      const task = this.taskQueue[this.currentTaskIndex];
      task.status = "processing";
      try {
        // 获取当前任务的图像对
        const currentPair = this.pairedImages[this.currentTaskIndex];

        // 创建FormData对象
        const leftFormData = new FormData();
        const rightFormData = new FormData();

        // 添加文件到FormData
        leftFormData.append("file", currentPair.leftEye.raw);
        rightFormData.append("file", currentPair.rightEye.raw);

        // 上传左眼图像
        const leftResponse = await request({
          method: "post",
          url: "/common/upload",
          data: leftFormData,
          headers: {
            "Content-Type": "multipart/form-data"
          }
        });

        // 上传右眼图像
        const rightResponse = await request({
          method: "post",
          url: "/common/upload",
          data: rightFormData,
          headers: {
            "Content-Type": "multipart/form-data"
          }
        });
        if (leftResponse.code === 200 && rightResponse.code === 200) {
          // 获取上传后的文件路径
          const leftImagePath = leftResponse.data;
          const rightImagePath = rightResponse.data;

          // TODO: 这里需要调用诊断API，传入图像路径进行诊断
          // 暂时使用模拟进度
          let progress = 0;
          const timer = setInterval(() => {
            progress += 20;
            this.processingPercentage = Math.floor((this.processedCount * 100 + progress) / this.totalProcessCount);
            if (progress >= 100) {
              clearInterval(timer);
              task.status = "completed";
              this.processedCount++;
              this.currentTaskIndex++;

              // 处理下一个任务
              this.processBatchTask();
            }
          }, 200);
        } else {
          throw new Error("文件上传失败");
        }
      } catch (error) {
        console.error("批量处理错误:", error);
        task.status = "error";
        this.$message.error(`任务 ${task.id} 处理失败`);

        // 继续处理下一个任务
        this.processedCount++;
        this.currentTaskIndex++;
        this.processBatchTask();
      }
    },
    updateBatchPatientDiagnosis() {
      // 更新批量患者诊断信息
      if (this.selectedPatientIds.length > 0 && this.batchResults.length > 0) {
        // 根据ID匹配结果和患者
        this.batchResults.forEach(result => {
          const patientId = result.id.split("_")[0]; // 假设格式为 PT2023001_left/right
          if (this.selectedPatientIds.includes(patientId)) {
            const patientIndex = this.patientList.findIndex(p => p.id === patientId);
            if (patientIndex !== -1) {
              const patient = this.patientList[patientIndex];
              const now = new Date();
              patient.leftEyeDiagnosis = result.leftEye.diagnosis;
              patient.leftEyeConfidence = result.leftEye.confidence;
              patient.rightEyeDiagnosis = result.rightEye.diagnosis;
              patient.rightEyeConfidence = result.rightEye.confidence;
              patient.finalDiagnosis = result.finalDiagnosis;
              patient.processTime = now.toLocaleString();
              this.$set(this.patientList, patientIndex, patient);
            }
          }
        });
      }
    },
    getTaskStatusText(status) {
      switch (status) {
        case "waiting":
          return "等待中";
        case "processing":
          return "处理中";
        case "completed":
          return "已完成";
        default:
          return "未知状态";
      }
    },
    percentageFormat(percentage) {
      return percentage + "%";
    },
    // 生成批量结果
    generateBatchResults() {
      // 模拟生成批量诊断结果
      this.batchResults = this.pairedImages.map(pair => {
        const leftEyeProbs = this.generateRandomProbabilities();
        const rightEyeProbs = this.generateRandomProbabilities();
        const leftMaxIndex = this.getMaxProbabilityIndex(leftEyeProbs);
        const rightMaxIndex = this.getMaxProbabilityIndex(rightEyeProbs);
        const result = {
          id: pair.id,
          leftEye: {
            diagnosis: this.diseaseCategories[leftMaxIndex],
            confidence: Math.round(leftEyeProbs[leftMaxIndex] * 100),
            probabilities: leftEyeProbs
          },
          rightEye: {
            diagnosis: this.diseaseCategories[rightMaxIndex],
            confidence: Math.round(rightEyeProbs[rightMaxIndex] * 100),
            probabilities: rightEyeProbs
          },
          finalDiagnosis: this.generateFinalDiagnosis(leftMaxIndex, rightMaxIndex),
          suggestion: this.generateSuggestion(leftMaxIndex, rightMaxIndex)
        };

        // 添加到历史记录
        this.addToHistory(result);
        return result;
      });
    },
    // 获取患者列表
    async fetchPatientList() {
      try {
        const response = await request({
          method: "get",
          url: "/patients/pageNow",
          params: {
            page: 1,
            pageSize: 10
          }
        });
        if (response.code === 200) {
          // 将后端返回的患者数据转换为前端需要的格式
          this.patientList = response.data.records.map(patient => ({
            id: patient.id,
            name: patient.patientName,
            gender: patient.gender,
            age: patient.age,
            phone: "",
            // 后端暂无此字段
            note: "",
            // 后端暂无此字段
            leftEyeDiagnosis: patient.leftEye || "",
            rightEyeDiagnosis: patient.rightEye || "",
            leftEyeConfidence: 0,
            // 后端暂无此字段
            rightEyeConfidence: 0,
            // 后端暂无此字段
            finalDiagnosis: patient.comprehensiveDiagnosis || "",
            processTime: patient.time || ""
          }));
        } else {
          this.$message.error(response.msg || "获取患者列表失败");
        }
      } catch (error) {
        console.error("获取患者列表错误:", error);
        this.$message.error("获取患者列表失败，请稍后重试");
      }
    },
    // 历史记录操作
    async fetchHistoryRecords() {
      try {
        const response = await request({
          method: "get",
          url: "/patients/pageHistory",
          params: {
            page: 1,
            pageSize: 10
          }
        });
        if (response.code === 200) {
          // 将后端返回的历史记录数据转换为前端需要的格式
          this.historyRecords = response.data.records.map(record => ({
            id: record.id,
            time: record.diagnosisTime,
            patientId: record.patientId,
            patientName: record.patientName,
            leftEye: {
              diagnosis: record.leftEye,
              confidence: 0,
              // 后端暂无此字段
              probabilities: [] // 后端暂无此字段
            },
            rightEye: {
              diagnosis: record.rightEye,
              confidence: 0,
              // 后端暂无此字段
              probabilities: [] // 后端暂无此字段
            },
            finalDiagnosis: record.comprehensiveDiagnosis
          }));
        } else {
          this.$message.error(response.msg || "获取历史记录失败");
        }
      } catch (error) {
        console.error("获取历史记录错误:", error);
        this.$message.error("获取历史记录失败，请稍后重试");
      }
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
    }

    // 获取患者列表
    this.fetchPatientList();

    // 获取历史诊断记录
    this.fetchHistoryRecords();
  }
};
